        # A diamond of "radius" k has vertices at distance k
        center_r = top + k
        center_c = left + k

        # Check top, bottom, left, right corners
        if matrix[top][center_c] != '1':
            return False
        if matrix[top + 2*k][center_c] != '1':
            return False
        if matrix[center_r][left] != '1':
            return False
        if matrix[center_r][left + 2*k] != '1':
