                if dc == 0 and -k <= dr <= k:
                    continue
                # Check if this cell should be part of the diamond
                if abs(dr) + abs(dc) == k and abs(dr) != k and abs(dc) != k:
                    # This is an edge point - already checked above
                    pass

    # More comprehensive check for foreign 1s
    for i in range(-k, k+1):
