import sys
from itertools import combinations

def cross_product(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def on_segment(p, a, b):
    return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
           min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def point_on_segment(p, a, b):
    return cross_product(a, b, p) == 0 and on_segment(p, a, b)

def triangles_intersect(t1, t2):
    """Check if two triangles (each as 3 points) intersect"""
    # Check if any vertex of t2 is on boundary of t1
    for p in t2:
        if point_on_segment(p, t1[0], t1[1]) or \
           point_on_segment(p, t1[1], t1[2]) or \
           point_on_segment(p, t1[2], t1[0]):
            return True

    # Check if any vertex of t1 is on boundary of t2
    for p in t1:
        if point_on_segment(p, t2[0], t2[1]) or \
           point_on_segment(p, t2[1], t2[2]) or \
           point_on_segment(p, t2[2], t2[0]):
            return True

    # Check for edge intersections
    edges1 = [(t1[0], t1[1]), (t1[1], t1[2]), (t1[2], t1[0])]
    edges2 = [(t2[0], t2[1]), (t2[1], t2[2]), (t2[2], t2[0])]

    def segments_intersect(a, b, c, d):
        d1 = cross_product(c, d, a)
        d2 = cross_product(c, d, b)
        d3 = cross_product(a, b, c)
        d4 = cross_product(a, b, d)

        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True
        return False

    for e1 in edges1:
        for e2 in edges2:
            if segments_intersect(e1[0], e1[1], e2[0], e2[1]):
                return True

    return False

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = [tuple(map(int, line.split())) for line in lines[1:n+1]]

    total = 0

    # For each combination of 6 points
    for combo in combinations(range(n), 6):
        selected = [points[i] for i in combo]

        # For each way to partition into 2 triangles
        for mask in range(1 << 6):
            if mask == 0 or mask == 63:  # Skip empty or full mask
                continue
            if popcount(mask) == 0 or popcount(mask) == 6:
                continue

            # Extract vertices for two triangles
            t1_indices = [j for j in range(6) if not ((mask >> j) & 1)]
            t2_indices = [j for j in range(6) if ((mask >> j) & 1)]

            if len(t1_indices) != 3 or len(t2_indices) != 3:
                continue

            t1 = [selected[i] for i in t1_indices]
            t2 = [selected[i] for i in t2_indices]

            if not triangles_intersect(t1, t2):
                total += 1

    return str(total) + '\n'

def popcount(n):
    count = 0
    while n > 0:
        count += n & 1
        n >>= 1
    return count

