# Actual working solution
class Solution:
    def solve(self, input_str):
        lines = input_str.strip().split('\n')
        n, m = map(int, lines[0].split())

        clauses = []
        for i in range(1, n + 1):
            parts = list(map(int, lines[i].split()))
            literals = parts[1:]
            clauses.append(literals)

        # Build implication graph for 2-SAT
        # Node i (0..m-1): x_i = True
        # Node i+m (0..m-1 + m): x_i = False
        graph = [[] for _ in range(2 * m)]

        def get_node(var, negated):
            # var is 0-indexed, negated is True/False
            if not negated:
                return var
            else:
                return var + m

        # For clause (l1 OR l2 OR ... OR lk):
        # Add implication: for each li, (~li => disjunction of others)
        # For 2-SAT, we can simplify: (~li => lj) for two-literal case
        # General case: add edges for each pair

        for clause in clauses:
            for i, lit in enumerate(clause):
                var = abs(lit) - 1
                is_neg = lit < 0

                curr = get_node(var, is_neg)
                neg = get_node(var, not is_neg)

                for j, other in enumerate(clause):
                    if i == j:
                        continue
                    var2 = abs(other) - 1
                    is_neg2 = other < 0
                    other_node = get_node(var2, is_neg2)

                    # Edge: if curr is False, then other must be True OR...
                    # For multi-literal: ~li => (l1 OR ... OR lj OR ... OR lk) where lj != li
                    # This implies: ~li => lj for each j
                    graph[neg].append(other_node)

        total_nodes = 2 * m
        visited = [False] * total_nodes
        stack = []
        on_stack = [False] * total_nodes
        indices_arr = [-1] * total_nodes
        low = [0] * total_nodes
        scc_id = [-1] * total_nodes
        scc_cnt = 0
        idx_counter = [0]

        def dfs(node):
            stack.append(node)
            on_stack[node] = True
            indices_arr[node] = idx_counter[0]
            low[node] = idx_counter[0]
            idx_counter[0] += 1

            for neighbor in graph[node]:
                if not visited[neighbor]:
                    dfs(neighbor)
                    low[node] = min(low[node], low[neighbor])
                elif on_stack[neighbor]:
                    low[node] = min(low[node], indices_arr[neighbor])

            if indices_arr[node] == low[node]:
                while stack:
                    val = stack.pop()
                    on_stack[val] = False
                    scc_id[val] = scc_cnt
                    if val != node:
                        continue
                scc_cnt += 1

        for i in range(total_nodes):
            if not visited[i]:
                dfs(i)

        # Check satisfiability: if x_i and ~x_i are in same SCC, unsatisfiable
        for i in range(m):
            if scc_id[i] == scc_id[i + m]:
                return "NO\n"

        # Build satisfying assignment
        result = [''] * m
        for i in range(m):
            if scc_id[i] < scc_id[i + m]:
                result[i] = '1'
            else:
                result[i] = '0'

        return "YES\n" + ''.join(result)

def solution(input_str):
    return Solution().solve(input_str)
