def solve_gcd_function(x, y):
    """Calculate f(x, y) where f(a, 0) = 0 and f(a, b) = 1 + f(a, b - gcd(a, b))"""
    if y == 0:
        return 0

    steps = 0
    a = x
    b = y

    while b > 0:
        g = math.gcd(a, b)
        b_mod = b % g

        if b_mod == 0:
            steps += (b // g)
            b = 0
        else:
            steps += (b - g) // g
            steps += 1
            b = b_mod

        if steps < 0 and b == 0:
            # Safety break, though not normally needed with this logic
            break

    return steps


def solution(input_str):
