Looking at this problem, I need to:

1. Find connected components and their sizes
2. Generate all lucky numbers (containing only digits 4 and 7) up to n
3. Use dynamic programming to find the minimum number of components needed to form each lucky number
4. The answer is (minimum components) - 1 (since merging k components requires k-1 roads)

```python
def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Union-Find for connectivity
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        p1, p2 = find(x), find(y)
        if p1 != p2:
            parent[p1] = p2
            return 1
        return 0

    # Process edges
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        union(u, v)

    # Find component sizes
    component_size = {}
    for i in range(1, n + 1):
        root = find(i)
        component_size[root] = component_size.get(root, 0) + 1

    sizes = list(component_size.values())

    # Generate lucky numbers up to n
    def generate_lucky(n):
        lucky = []
        def dfs(current, length):
            if current > n:
                return
            if current > 0:
                lucky.append(current)
            for digit in [4, 7]:
                next_val = current * 10 + digit
                if next_val <= n:
                    dfs(next_val, length + 1)
        dfs(0, 0)
        return sorted(lucky)

    lucky_numbers = generate_lucky(n)

    if not lucky_numbers:
        return "-1\n"

    # DP: dp[v] = minimum number of components that sum to size v
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0

    # Process each component size
    for s in sizes:
        # Process in reverse to avoid using same component multiple times
        for v in range(n, s - 1, -1):
            if dp[v - s] != INF:
                dp[v] = min(dp[v], dp[v - s] + 1)

    # Find minimum roads for any lucky number
    min_roads = INF
    for L in lucky_numbers:
        if dp[L] != INF:
            # Roads needed = components - 1
            min_roads = min(min_roads, dp[L] - 1)

    if min_roads == INF:
        return "-1\n"

    return f"{min_roads}\n"


if __name__ == "__main__":
    import sys
    print(solution(sys.stdin.read()))
```

