def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    adj = [[] for _ in range(N)]
    for i in range(1, len(lines)):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    from collections import deque
    visited = [False] * N
    component_sizes = []

    for start in range(N):
        if not visited[start]:
            visited[start] = True
            count = 1
            q = deque([start])
            while q:
                v = q.popleft()
                for u in adj[v]:
                    if not visited[u]:
                        visited[u] = True
                        count += 1
                        q.append(u)
            component_sizes.append(count)

    total = sum(s * (s + 1) // 2 for s in component_sizes)
    return str(total)
