def solution(input_str):
    # Parse input - handle both single-line and multi-line formats
    parts = input_str.strip().split()
    h, m, k = int(parts[0]), int(parts[1]), int(parts[2])
    h1, m1 = int(parts[3]), int(parts[4])
    h2, m2 = int(parts[5]), int(parts[6])

    ha = len(str(h - 1))
    ma = len(str(m - 1))

    def time_str(mn):
        hh, mm = mn // m, mn % m
        return f"{hh:0{ha}d}:{mm:0{ma}d}"

    def digit_changes(mn1, mn2):
        s1, s2 = time_str(mn1), time_str(mn2)
        return sum(c1 != c2 for c1, c2 in zip(s1, s2))

    start = h1 * m + m1
    end = h2 * m + m2

    if start == end:
        return "0"

    total = 0
    if start > end:
        for i in range(start, h * m):
            total += 1 if digit_changes(i, i + 1) >= k else 0
        for i in range(0, end):
            total += 1 if digit_changes(i, i + 1) >= k else 0
    else:
        for i in range(start, end):
            total += 1 if digit_changes(i, i + 1) >= k else 0

    return f"{total}\n"
