        if n_str is None:
            break

        n = int(n_str)
        tree = []

        for i in range(n):
            line = next(reader, '').strip()
            parts = list(map(str, line.split()))
            value = int(parts[0])
            l, r = -1, -1
            if value == -1:
                l = int(parts[1])
                r = int(parts[2])
            tree.append((value, l, r))

        def compute_leaves(node):
            if tree[node][0] != -1:
                return 1
            return compute_leaves(tree[node][1]) + compute_leaves(tree[node][2])

        def solve_tree(node):
            if tree[node][0] != -1:
                return tree[node][0]

            count_left = compute_leaves(tree[node][1])
            count_right = compute_leaves(tree[node][2])
            total_leaves_in_subtree = count_left + count_right
            count = total_leaves_in_subtree

            val_left = solve_tree(tree[node][1])
            val_right = solve_tree(tree[node][2])

            # Merge at this node: Pieguy moves if count - 1 is odd
            if (count - 1) % 2 == 1:
                return max(val_left, val_right)
            else:
                return min(val_left, val_right)

        results.append(str(solve_tree(0)))

    return '\n'.join(results)

