            if self.max_count < bin(mask).count('1'):
                self.max_count = bin(mask).count('1')
            return

        # Pruning: upper bound
        remaining = n - idx
        if bin(mask).count('1') + remaining <= self.max_count:
            return

        # Option 1: include node idx
        can_include = True
        for j in range(idx):
            if (mask >> j) & 1 and adj[idx][j]:
                can_include = False
                break
        if can_include:
            new_mask = mask | (1 << idx)
            search(idx + 1)

        # Option 2: exclude node idx
        if not self.include[idx]:
            new_mask = mask
            search(idx + 1)

    return self.max_count
