def solution(expression: str) -> str:
    MOD = 10**9 + 7

    pos = 0
    n = len(expression)

    def parse_number():
        nonlocal pos
        if pos >= n or not expression[pos].isdigit():
            return None
        start = pos
        while pos < n and expression[pos].isdigit():
            pos += 1
        return int(expression[start:pos])

    def parse_term():
        nonlocal pos
        l = parse_number()
        if l is None:
            return None  # This shouldn't happen with valid input

        if pos >= n or expression[pos] == '+':
            # Single number term
            return l

        if pos < n and expression[pos] == '-':
            pos += 1  # skip '-'
            r = parse_number()
            if r is None:
                return None
            # Range l to r (inclusive)
            return compute_range(l, r)

        if pos < n and expression[pos] == '(' and pos + 1 < n and expression[pos + 1] != ')':
            # <number>(<expression>) - repetition
            pos += 1  # skip '('
            expr = parse_expression()
            pos += 1  # skip ')'
            return compute_repetition(l, expr)

        return l

    def parse_expression():
        nonlocal pos
        result = []
        while pos < n:
            term = parse_term()
            if term is None:
                break
            result.append(term)
            if pos < n and expression[pos] == '+':
                pos += 1  # skip '+'
            else:
                break
        return result

    def compute_range(l: int, r: int) -> int:
        # Concatenate all integers from l to r
        # We need to compute this modulo MOD
        result = 0
        for i in range(l, r + 1):
            s = str(i)
            # result = result * 10^len(s) + value
            result = (result * pow(10, len(s), MOD) + i) % MOD
        return result

    def compute_repetition(count: int, expr: list) -> int:
        # Concatenate count repetitions of expr
        result = 0
        for i in range(count):
            for term in expr:
                result = (result * pow(10, term_length(term), MOD) + term) % MOD
        return result

    def term_length(t: int) -> int:
        return len(str(t))

    def parse_all():
        nonlocal pos
        # Process the full expression
        result = []
        while pos < n:
            term = parse_term()
            if term is None:
                break
            result.append(term)
            if pos < n and expression[pos] == '+':
                pos += 1
            else:
                break
        return result

    terms = parse_all()

    # Compute final result by concatenating all terms
    result = 0
    for i, term in enumerate(terms):
        if i > 0:
            result = (result * pow(10, len(str(term)), MOD) + term) % MOD
        else:
            result = term

    return str(result) + '\n'
