def min_dist_to_origin(p0: Tuple[float, float], p1: Tuple[float, float]) -> float:
    """Find minimum distance from origin to the line segment p0-p1."""
    dx = p1[0] - p0[0]
    dy = p1[1] - p0[1]

    dot = p0[0] * dx + p0[1] * dy
    length_sq = dx * dx + dy * dy

    if abs(length_sq) < 1e-12:
