            dist0 = math.sqrt((t_pts[0][0] - q_x)**2 + **(t_pts[0][1] - q_y)2)
            dist1 = math.sqrt((t_pts[1][0] - q_x)**2 + **(t_pts[1][1] - q_y)2)

            return min(dist0, dist1) / v <= t

