import random
from typing import List

def verify_stable_matching(n: int, costs: List[List[int]], matching: List[int]) -> bool:
    """
    Verify if all cities are properly matched.
    """
    for i in range(n):
        j = matching[i]
        if j == -1 or matching[j] != i:
            return False
    return True

def is_stable(n: int, costs: List[List[int]], matching: List[int]) -> bool:
    """
    Check if the matching is stable - no blocking pairs exist.
    A blocking pair (i,j) exists when both i and j would prefer to pair 
    with each other than with their current partners.
    """
    for i in range(n):
        for j in range(n):
            if i != j and matching[i] != j and matching[j] != i:
                # Both prefer to pair with each other
                if costs[i][j] < costs[i][matching[i]] and costs[j][i] < costs[j][matching[j]]:
                    return False
    return True

def find_stable_matching(n: int, costs: List[List[int]]) -> List[int]:
    """
    Find a stable matching using greedy approach with multiple trials.
    Returns the matching where matching[i] is the partner of city i (0-indexed).
    Returns [-1, -1, ..., -1] if no stable matching is found.
    """
    best_matching = [-1] * n

    # Try multiple random orderings
    for attempt in range(500):
        # Randomly shuffle the order of cities to process
        order = list(range(n))
        random.seed(12345 + attempt)
        random.shuffle(order)

        # Initialize matching with each city matched to itself temporarily
        temp_matching = list(range(n))

        # Process cities in random order to find better matching
        for i in order:
            # Find best available partner
            best = -1
            for j in range(n):
                if i != j and temp_matching[j] == i:  # j is free (temp_matching[j] == i is placeholder)
                    continue  # j is already matched to someone else
                if best == -1 or costs[i][j] < costs[i][temp_matching[i]]:
                    best = j

            temp_matching[i] = best

    # Try deterministic greedy approach
    matching = [-1] * n
    for i in range(n):
        best = -1
        for j in range(n):
            if i != j and matching[j] == -1:
                if best == -1 or costs[i][j] < costs[i][best if best != -1 else 0]:
                    best = j
        if best != -1:
            matching[i] = best
            matching[best] = i

    # Try multiple times with different random seeds
    for attempt in range(100):
        matching = [-1] * n

        # Greedy assignment
        for _ in range(min(n, 200)):
            best_i = -1
            for i in range(n):
                if matching[i] != -1:
                    continue
                best_j = -1
                for j in range(n):
                    if i != j and matching[j] == -1:
                        if best_j == -1 or costs[i][j] < costs[i][best_j if best_j != -1 else 0]:
                            best_j = j
                if best_j != -1:
                    matching[i] = best_j
                    matching[best_j] = i

        # Try to pair remaining unmatched cities
        unmatched = [i for i in range(n) if matching[i] == -1]
        if len(unmatched) >= 2:
            i, j = unmatched[0], unmatched[1]
            matching[i] = j
            matching[j] = i
            # Adjust others
            for k in range(n):
                if k not in [i, j] and matching[k] == matching[i]:
                    matching[k] = -1

        # Verify matching
        if verify_stable_matching(n, costs, matching):
            if is_stable(n, costs, matching):
                return matching

    return [-1] * n

def solution(input_str: str) -> str:
    """
    Solve the stable rail pairing problem.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n = int(lines[0])

    if n == 0:
        return "-1\n"

    # Parse costs matrix
    # Each row i contains n-1 integers (costs to all other cities, excluding self)
    fees = [[0] * n for _ in range(n)]

    for i in range(n):
        row = list(map(int, lines[1 + i].split() if 1 + i < len(lines) else []))
        idx = 0
        for j in range(n):
            if j != i:
                if j < i:
                    fees[i][j] = row[idx]
                else:
                    fees[i][j] = row[idx + 1]
                idx += 1

    has_valid = False
    for i in range(n):
        for j in range(n):
            if i != j and fees[i][j] <= 0:
                has_valid = False
                break
        if not has_valid:
            continue

    has_valid = True

    if n < 2:
        return "-1\n"

    result = find_stable_matching(n, fees)

    output_lines = []
    for m in result:
        if m != -1:
            output_lines.append(str(m + 1))
        else:
            output_lines.append("-1")

    return '\n'.join(output_lines) + '\n' if output_lines else "-1\n"

