    for i in range(1, n + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            r, h = int(parts[0]), int(parts[1])
            volume = math.pi * r * r * h
            cake_volumes.append(volume)

    # Coordinate compression for volumes
    sorted_volumes = sorted(set(cake_volumes))
    volume_rank = {v: i + 1 for i, v in enumerate(sorted_volumes)}
    max_rank = len(sorted_volumes)

    # Fenwick tree for range maximum query
    bit = [0.0] * (max_rank + 2)

    def update(idx, val):
        while idx <= max_rank:
            bit[idx] = max(bit[idx], val)
            idx += idx & (-idx)

    def query(idx):
        result = 0.0
        while idx > 0:
            result = max(result, bit[idx])
            idx -= idx & (-idx)
        return result

    dp = 0.0
    for volume in cake_volumes:
        rank = volume_rank[volume]
        # Query max dp for strictly smaller volumes (rank - 1)
        best_prev = query(rank - 1)
        current = best_prev + volume
        update(rank, current)
        if current > dp:
            dp = current

    return str(dp)

