        while idx <= max_rank:
            bit[idx] = max(bit[idx], val)
            idx += idx & (-idx)

    def query(idx):
        result = 0.0
        while idx > 0:
            result = max(result, bit[idx])
            idx -= idx & (-idx)
        return result

