        return result if result else "0"

    # Build KMP transition
    pi = [0] * mv
    for i in range(1, mv):
        j = 0
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    def get_trans(state, ch):
        while state > 0 and virus[state] != ch:
            state = pi[state - 1]
        if virus[state] == ch:
            state += 1
        return state if state <= mv else mv

    # 2D DP where we track k
    dp = {}
    best = 0

    for i in range(m1 + 1):
        for j in range(m2 + 1):
            for k in range(mv + 1):
                key = (i, j, k)
                if key not in dp:
                    dp[key] = 0
                    continue

                if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                    c = s1[i-1]
                    nk = get_trans(k, c)
                    prev = dp.get((i-1, j-1, 0), 0)
                    if prev + 1 > dp[(i,j,k)]:
                        dp[(i,j,k)] = prev + 1

    # Navigate backwards
    res = []
    i, j, k = m1, m2, 0
    while i > 0 and j > 0:
        if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
            c = s1[i-1]
            nk = get_trans(k, c)
            if dp.get((i,j,nk), 0) == dp.get((i-1,j-1,k), 0) + 1:
                res.append(c)
                i -= 1
                j -= 1
                k = nk
                continue
        i -= 1 if i > j else j -= 1

    return "".join(reversed(res)) or "0"
