            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # DP: dp[i][j][k] = max LCS length
    dp = [[[0] * (mv + 1) for _ in range(m2 + 1)] for _ in range(m1 + 1)]
    par = [[[(-1, -1, -1)] * (mv + 1) for _ in range(m2 + 1)] for _ in range(m1 + 1)]

    for i in range(m1 + 1):
        for j in range(m2 + 1):
            for k in range(mv + 1):
                if i < m1 or j < m2:
                    if i - 1 >= 0:
                        if dp[i-1][j][k] >= dp[i][j][k]:
                            par[i][j][k] = (i-1, j, k)
                    if j - 1 >= 0:
                        if dp[i][j-1][k] >= dp[i][j][k]:
                            par[i][j][k] = (i, j-1, k)

                if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                    nk = k + 1 if k < mv and virus[k] == s1[i-1] else 0
                    if nk <= mv:
