                            dp[i][j][nk] = dp[i-1][j-1][k] + 1
                            par[i][j][nk] = (i-1, j-1, k)

    # Find max
    best = 0
    bestk = 0
    for k in range(mv + 1):
        if dp[m1][m2][k] > best:
            best = dp[m1][m2][k]
            bestk = k

    if best == 0:
        return "0"

    # Reconstruct
    res = []
    i, j, k = m1, m2, 0
    while i > 0 and j > 0:
        p = par[i][j][k]
        if p[0] == i - 1 and p[1] == j - 1 and p[2] == k:
