    if not lines:
        return "EMPTY SET"

    n = int(lines[0])

    # Dictionary to store active pairs by their query index (1-indexed)
    pairs = {}

    # List to store results for type 3 queries
    results = []

    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])

        if t == 1:
            # Add a pair (a, b)
            pairs[i] = (int(parts[1]), int(parts[2]))
        elif t == 2:
            # Remove a pair from query i
            idx = int(parts[1])
            if idx in pairs:
                del pairs[idx]
        elif t == 3:
            # Query: find max(a*q + b) over all pairs
            q = int(parts[1])
            if not pairs:
                results.append("EMPTY SET")
            else:
                max_val = None
                for idx, (a, b) in pairs.items():
                    val = a * q + b
                    if max_val is None or val > max_val:
                        max_val = val
                results.append(str(max_val))

    # Join results with newlines
    return '\n'.join(results)
