def solution(input_str):
    from functools import lru_cache

    lines = input_str.strip().split('\n')

    parts = lines[0].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])

    # Check basic validity
    path_length = n + m - 1
    if path_length % 2 != 0:
        return ""

    # Read priorities
    priorities = []
    for i in range(n):
        row_prios = []
        for line in lines[1:n+1]:
            if row_prios:
                break
            for val in line.split():
                row_prios.append(int(val))
        priorities.append(row_prios)

    # Cell list with (priority, row, col)
    cells = []
    pos = 1
    for i in range(n):
        for j in range(m):
            if pos < len(lines[pos].split()):
                pr = priorities[i][j]
            cells.append((pr, i, j))

    cells.sort(key=lambda x: (x[0], x[1], x[2]))

    # Maximum possible balance needed - path length + 1
    MAX_BAL = path_length + 3

    # dp[i][j][bal] = count of valid paths from (0,0) to (i,j) ending with balance 'bal'
    dp = [[[0] * MAX_BAL for _ in range(m)] for _ in range(n)]

    @lru_cache(maxsize=None)
    def count_endings(i, j, bal):
        """Count valid paths from (i,j) to (n-1,m-1) with current balance"""
        if i >= n or j >= m:
            return 0
        if bal < 0:
            return 0
        if i == n - 1 and j == m - 1:
            return 1 if bal == 0 else 0

        total = 0
        # Can go right (next cell uses same balance as current when we go there)
        if j + 1 < m:
            total += count_endings(i, j + 1, bal)
        # Can go down
        if i + 1 < n:
            total += count_endings(i + 1, j, bal)

        return total

    def compute_dp_tables():
        """Precompute valid path counts"""
        dp = [[[0] * MAX_BAL for _ in range(m)] for _ in range(n)]

        # Start from (0,0) with balance 0 (before placing any bracket)
        # After placing '(', balance becomes 1
        dp[0][0][0] = 1  # Virtual state: before placing bracket at (0,0)

        for i in range(n):
            for j in range(m):
                for bal in range(MAX_BAL):
                    if dp[i][j][bal] > 0:
                        # Try placing '(' -> new_bal = bal + 1
                        if bal + 1 < MAX_BAL:
                            if j + 1 < m:
                                dp[i][j+1][bal+1] += dp[i][j][bal]
                            if i + 1 < n:
                                dp[i+1][j][bal+1] += dp[i][j][bal]
                        # Try placing ')' -> new_bal = bal - 1
                        if bal - 1 >= 0:
                            if i + 1 < n:
                                dp[i+1][j][bal-1] += dp[i][j][bal]
                            if j + 1 < m:
                                dp[i][j+1][bal-1] += dp[i][j][bal]

        return dp

    dp_table = compute_dp_tables()

    # Result grid
    result = [['' for _ in range(m)] for _ in range(n)]

    # Fill path tracking
    for i in range(n):
        for j in range(m):
            result[i][j] = '(' if (paths[i][j][0] % 2 == 1) else ')'

    return '\n'.join(''.join(row) for row in result)
